import tkinter as tk
from tkinter import ttk, messagebox
from ..dataset_gui import DatasetManagerGUI
from ..file_placer_gui import ProjectFilePlacerGUI

class DatasetTab(ttk.Frame):
    def __init__(self, master, app):
        super().__init__(master)
        self.app = app
        self._build_ui()

    def _build_ui(self):
        f = tk.LabelFrame(self, text="Project Tools")
        f.pack(fill=tk.X, padx=10, pady=10)

        self.cb_dataset = ttk.Combobox(f, textvariable=self.app.manage_project_var, values=self.app.available_projects)
        self.cb_dataset.pack(side=tk.LEFT, padx=5, pady=5)

        ttk.Button(f, text="File Placer", command=self.launch_file_placer).pack(side=tk.LEFT, padx=5)
        ttk.Button(f, text="Point Selector", command=self.launch_dataset_manager).pack(side=tk.LEFT, padx=5)

    def launch_file_placer(self):
        p = self.app.manage_project_var.get()
        if p: ProjectFilePlacerGUI(self.app, p)

    def launch_dataset_manager(self):
        p = self.app.manage_project_var.get()
        if not p: return

        try:
            files = self.app.project_manager.get_project_file_paths(p)
            imgs = [cfg['path'] for cfg in files.get('calibration_image_configs', [])]
            if imgs:
                # We don't pass a file path anymore, we pass the project name so it can use DB config
                DatasetManagerGUI(tk.Toplevel(self.app), imgs, p)
            else: 
                messagebox.showinfo("Info", "No calibration images found.")
        except Exception as e:
            messagebox.showerror("Error", f"Failed to load project files: {e}")

